            send_message("w3 правый")
        }
        cancel_event()
    }
}

when player_chat {
    if chat_message_equals("@w3") {
        cancel_event()
        set_gamemode(gamemode: creative)
        clear_inventory()
        give_items(item(wooden_axe))
        w3_ahead = shift_location_in_direction(value.eye_location, 2)
        w3_spot = align_location(w3_ahead, rotation_mode: remove)
        set_block(w3_spot, block(stone))
        send_message("w3 готов")
    }
    if chat_message_equals("@w3set") {
        cancel_event()
        if var.exists(`w3_pos1 %player%`) and var.exists(`w3_pos2 %player%`) {
            set_region(block(glass), `w3_pos1 %player%`, `w3_pos2 %player%`)
            wait(2)
            w3_set = game.block_equals(block(glass), `w3_pos1 %player%`)
            send_message("w3 заполнено ${w3_set}")
            clear_region(`w3_pos1 %player%`, `w3_pos2 %player%`)
            wait(2)
            w3_gone = game.block_equals(block(air), `w3_pos1 %player%`)
            send_message("w3 убрано ${w3_gone}")
        }
    }
}

const W4_PER_TICK = 50
const W4_CPU_MAX = 70

func w4_pace() {
    w4_steps += 1
    if w4_steps >= W4_PER_TICK {
        w4_steps = 0
        wait(1)
    }
    while value.cpu_usage >= W4_CPU_MAX {
        wait(1)
    }
}

func w4_ball(w4_c: location, w4_r: number, w4_b: block) {
    w4_from = shift_all_coordinates(w4_c, -3, -3, -3)
    w4_to = shift_all_coordinates(w4_c, 3, 3, 3)
    on_grid(w4_p, w4_from, w4_to) {
        w4_cells += 1
        if location_is_near(w4_p, w4_r, w4_c) {
            set_block(w4_p, w4_b)
            w4_set += 1
        }
        w4_pace()
    }
}

when player_chat {
    if chat_message_equals("@w4") {
        cancel_event()
        w4_base = align_location(value.location, rotation_mode: remove, align_mode: corner)
        w4_mid = shift_coordinate(w4_base, 10, type: y)
        w4_ball(w4_mid, 2.5, block(glass))
        send_message("w4 клеток ${w4_cells}")
        send_message("w4 шар ${w4_set}")
        w4_in = game.block_equals(block(glass), w4_mid)
        send_message("w4 внутри ${w4_in}")
        w4_edge = shift_all_coordinates(w4_mid, 3, 3, 3)
        w4_empty = game.block_equals(block(air), w4_edge)
        send_message("w4 угол пуст ${w4_empty}")
        send_message("w4 нагрузка ${value.cpu_usage}")
        send_message("w4 tps ${value.server_tps}")
        clear_region(shift_all_coordinates(w4_mid, -3, -3, -3), w4_edge)
        wait(2)
        w4_gone = game.block_equals(block(air), w4_mid)
        send_message("w4 убрано ${w4_gone}")
    }
}

