func w6_fill(w6_b: block, w6_p1: location, w6_p2: location) {
    w6_lo = min([get_coordinate(w6_p1, type: x), get_coordinate(w6_p2, type: x)])
    w6_hi = max([get_coordinate(w6_p1, type: x), get_coordinate(w6_p2, type: x)])
    for w6_x in w6_lo..w6_hi {
        set_region(w6_b, set_coordinate(w6_p1, w6_x, type: x), set_coordinate(w6_p2, w6_x, type: x))
        w6_parts += 1
        wait(1)
    }
}

when player_chat {
    if chat_message_equals("@w6") {
        cancel_event()
        w6_base = align_location(value.location, rotation_mode: remove)
        w6_a = shift_coordinate(w6_base, 8, type: y)
        w6_b = shift_all_coordinates(w6_a, 5, 0, 5)
        w6_fill(block(stone), w6_b, w6_a)
        send_message("w6 срезов ${w6_parts}")
        w6_one = game.block_equals(block(stone), w6_a)
        send_message("w6 угол 1 ${w6_one}")
        w6_two = game.block_equals(block(stone), w6_b)
        send_message("w6 угол 2 ${w6_two}")
        w6_fill(block(air), w6_a, w6_b)
        w6_gone = game.block_equals(block(air), w6_b)
        send_message("w6 убрано ${w6_gone}")
    }
}

