func w8_guard(w8_l: location) {
    for w8_z in w8_zones {
        if w8_z["owner"] != value.name and location_in_range(w8_l, w8_z["a"], w8_z["b"], border_handling: block) {
            cancel_event()
            send_message("w8 приват ${w8_z["owner"]}")
            return
        }
    }
}

when player_break_block {
    w8_guard(value.event_block_location)
}

when player_place_block {
    w8_guard(value.event_block_location)
}

