save w10_warps
game `w10_home %player%`

when player_chat {
    w10_args = split_text(value.event_chat_message, " ")
    w10_name = get_list_value(w10_args, 1, "")
    if w10_args[0] == "@w10" {
        cancel_event()
        set_gamemode(gamemode: creative)
        `w10_home %player%` = value.location
        w10_warps = create_map()
        w10_warps["hub"] = loc(3.5, 30, 3.5, 90, 0)
        set_spawn_point(`w10_home %player%`)
        send_message("w10 готов")
    }
    if w10_args[0] == "@w10go" {
        cancel_event()
        if w10_name in w10_warps {
            player.teleport(w10_warps[w10_name], keep_rotation: false)
            wait(2)
            w10_yaw = round(value.yaw)
            send_message("w10 поворот ${w10_yaw}")
        } else {
            send_message("w10 нет точки ${w10_name}")
        }
    }
    if w10_args[0] == "@w10keep" {
        cancel_event()
        w10_before = value.yaw
        player.teleport(loc(3.5, 30, 3.5, 10, 0))
        wait(2)
        w10_same = abs(value.yaw - w10_before) < 1
        send_message("w10 поворот сохранён ${w10_same}")
    }
    if w10_args[0] == "@w10back" {
        cancel_event()
        player.teleport(`w10_home %player%`, keep_rotation: false)
        send_message("w10 назад")
    }
}

