func w11_tick() {
    if player.in_area(`w11_a %player%`, `w11_b %player%`, ignore_y_axis: false) {
        if `w11_in %player%` != 1 {
            `w11_in %player%` = 1
            send_message("w11 вошёл")
        }
    } else if `w11_in %player%` == 1 {
        `w11_in %player%` = 0
        send_message("w11 вышел")
    }
}

